{"name": "estimate_total_time_v2", "code": "import math

def solve(inputs: dict) -> float:
    percentage_completed = inputs['PERCENTAGE_COMPLETED'] / 100
    time_spent = inputs['TIME_SPENT']
    # If the percentage completed is greater than 100%, apply a correction factor
    if percentage_completed > 1:
        correction_factor = math.log(percentage_completed)
        estimated_total_time = time_spent * correction_factor
    else:
        remaining_percentage = 1 - percentage_completed
        estimated_total_time = time_spent / remaining_percentage
    return estimated_total_time"}

